// 2026-10-12 (barrel1), HIS ANSWER 7 a: "clearly marked (e.g. red barrels with X on em?)". EXPLOSIVE BARRELS. Every live raid (DEMO and
// CAREER alike, his answer that gameplay is the same in both) gets clusters of one to three red barrels with a white X, placed by
// brlPlace on their own side stream (BRL_TAG), so the seeded stream, the ents and the containers are exactly what they were, and the
// bot raid has none. Any round that reaches a barrel stops in it (brlShot); BRL_HP of damage lights it, and a lit barrel flickers for
// a moment and goes up (brlTick, brlBlast). The blast hurts everyone near it in line of sight: the player, machines, pillagers, and
// the walls as a charge does, and it lights every barrel inside it after a short beat, so a cluster goes up in a chain. A charge
// lights them too. Kills go to the player whose round or charge lit it (by), none for an enemy round. His rule of no team damage
// holds: a barrel a player lit never hurts another player of the party. Cosmetic draws use no stream.
var BRL_TAG=47, BRL_CL=13, BRL_HP=30, BRL_R=170, BRL_HIT=13;
function brlMe(){ return (typeof NET==='object'&&NET&&NET.on&&NET.role==='join')?Math.max(1,NET.seat|0):0; }
function brlOk(g,x,y){
  var i, m=g.map, p=g.player;
  if(!spotFree(m,x,y,16)) return false;
  if(p&&Math.hypot(x-p.x,y-p.y)<460) return false;
  for(i=0;i<(m.extracts||[]).length;i++) if(Math.hypot(x-m.extracts[i].x,y-m.extracts[i].y)<240) return false;
  for(i=0;i<g.containers.length;i++) if(Math.hypot(x-g.containers[i].x,y-g.containers[i].y)<36) return false;
  for(i=0;i<g.brl.length;i++) if(Math.hypot(x-g.brl[i].x,y-g.brl[i].y)<24) return false;
  try{ if(inWaterMap(m,x,y)) return false; }catch(_w){}
  return true;
}
function brlPlace(g){
  g.brl=[];
  if(!g||g.sim||!g.map||!Array.isArray(g.containers)) return;
  sideStream(g.seed,BRL_TAG,function(){
    var c, t, s, q, k, j, a, d, x, y;
    for(c=0;c<BRL_CL;c++){
      s=null;
      for(t=0;t<40&&!s;t++){ q=freeSpot(g.map,26); if(brlOk(g,q.x,q.y)) s=q; }
      if(!s) continue;
      g.brl.push({id:g.brl.length,x:s.x,y:s.y,hp:BRL_HP,fuse:-1,by:-1,gone:0});
      k=Math.floor(rr()*3);
      for(j=0;j<k;j++){
        for(t=0;t<12;t++){
          a=rr()*6.2832; d=26+rr()*16; x=s.x+Math.cos(a)*d; y=s.y+Math.sin(a)*d;
          if(brlOk(g,x,y)){ g.brl.push({id:g.brl.length,x:x,y:y,hp:BRL_HP,fuse:-1,by:-1,gone:0}); break; }
        }
      }
    }
  });
}
function brlLight(B,by,fuse){
  if(!B||B.gone||B.fuse>=0) return false;
  B.fuse=fuse; B.by=by;
  return true;
}
function brlShot(b){
  var i, B, L=G.brl;
  for(i=0;i<L.length;i++){
    B=L[i]; if(B.gone) continue;
    if(Math.abs(b.x-B.x)>BRL_HIT||Math.abs(b.y-(B.y-10))>BRL_HIT+4) continue;
    B.hp-=(+b.dmg||0);
    if(!G.sim){ spark(b.x,b.y,'#ffb070',8,180); sfx('clank',b.x,b.y,'metal'); }
    if(B.hp<=0) brlLight(B,b.player?brlMe():-1,0.06);
    return true;
  }
  return false;
}
function brlNear(x,y,R,by){
  var i, B, d;
  for(i=0;i<(G.brl||[]).length;i++){
    B=G.brl[i]; if(B.gone||B.fuse>=0) continue;
    d=Math.hypot(B.x-x,B.y-y);
    if(d<R) brlLight(B,by,0.12+0.22*d/R);
  }
}
function brlTick(dt){
  var i, B;
  if(!G||!G.brl||!G.brl.length) return;
  for(i=0;i<G.brl.length;i++){
    B=G.brl[i]; if(B.gone||B.fuse<0) continue;
    B.fuse-=dt;
    if(B.fuse<=0) brlBlast(B);
  }
}
function brlBlast(B){
  var p=G.player, R=BRL_R, x=B.x, y=B.y, s=B.by, me=brlMe(), i, e, de, dm, sd, bp={x:x,y:y}, peer=netEntsPeer(), W, w, cx, cy, dd;
